style.css:
@-moz-document domain("google.com") {
:root {
        --my-ocean: #071827;
        --my-deep: #102c40;
        --my-gold: #e8b84b;
        --my-red: #bd3935;
        --my-paper: #f3e7c9;
    }

    /* FUNDO GRAND LINE */
    html,
    body {
        background-color: var(--my-ocean) !important;

        /* background-image: url("<a href="https://ibb.co/hJzfmgJq"><img src="https://i.ibb.co/v6nYjc6t/P-r-Sol-na-Grand-Line.png" alt="P-r-do-Sol-na-Grand-line" border="0" /></a>") !important; */

        background-position: center center !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;

        color: var(--my-paper) !important;
    }

    /* ÁREAS PRINCIPAIS */
    #appbar,
    #top_nav,
    #cnt,
    #rcnt,
    #center_col,
    #rhs {
        background: transparent !important;
        color: var(--my-paper) !important;
    }

    /* CAIXA DE PESQUISA */
    .RNNXgb {
        background: var(--my-deep) !important;
        border: 2px solid var(--my-gold) !important;
        border-radius: 28px !important;
        box-shadow: 0 4px 18px #0008 !important;
    }

    #APjFqb {
        color: var(--my-paper) !important;
        background: transparent !important;
    }

    /* RESULTADOS DE PESQUISA */
    .MjjYud,
    .g,
    .tF2Cxc {
        background: rgba(7, 24, 39, 0.88) !important;
        border: 1px solid rgba(232, 184, 75, 0.25) !important;
        border-radius: 12px !important;
        padding: 12px !important;
        margin-bottom: 12px !important;
    }

    /* TÍTULOS */
    h1,
    h2,
    h3,
    .LC20lb {
        color: var(--my-gold) !important;
    }

    /* LINKS */
    a,
    a:visited {
        color: var(--my-gold) !important;
    }

    a:hover {
        color: var(--my-red) !important;
    }

    /* TEXTOS */
    p,
    span,
    label {
        color: var(--my-paper);
    }

    /* BOTÕES */
    button,
    input[type="submit"] {
        background: var(--my-red) !important;
        color: var(--my-paper) !important;
        border: 1px solid var(--my-gold) !important;
        border-radius: 10px !important;
    }

    button:hover,
    input[type="submit"]:hover {
        background: var(--my-gold) !important;
        color: var(--my-ocean) !important;
    }

    /* SELEÇÃO DE TEXTO */
    ::selection {
        background: var(--my-gold) !important;
        color: var(--my-ocean) !important;
    }
}
